package org.apache.commons.compress.utils;

import java.io.*;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ChecksumCalculatingInputStream_read_TriageGen2Test {

    @Test
    public void testRead_ReturnsDataAndUpdatesChecksum() throws IOException {
        // Arrange
        byte[] data = new byte[]{(byte) 0xAB};
        InputStream inputStream = new InputStream() {
            private int pos = 0;
            @Override
            public int read() throws IOException {
                return (pos < data.length) ? (data[pos++] & 0xFF) : -1;
            }
        };
        Checksum checksum = mock(Checksum.class);
        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(checksum, inputStream);

        // Act
        int result = cis.read();

        // Assert
        assertEquals(0xAB, result);
        verify(checksum).update(0xAB);
    }

    @Test
    public void testRead_ReturnsEOFAndDoesNotUpdateChecksum() throws IOException {
        // Arrange
        InputStream inputStream = new InputStream() {
            @Override
            public int read() throws IOException {
                return -1;
            }
        };
        Checksum checksum = mock(Checksum.class);
        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(checksum, inputStream);

        // Act
        int result = cis.read();

        // Assert
        assertEquals(-1, result);
        // Verify update was never called because ret < 0
        verify(checksum, org.mockito.Mockito.never()).update(org.mockito.ArgumentMatchers.anyInt());
    }

    @Test
    public void testRead_ThrowsIOException() throws IOException {
        // Arrange
        InputStream inputStream = mock(InputStream.class);
        when(inputStream.read()).thenThrow(new IOException("Simulated IO error"));
        Checksum checksum = new CRC32();
        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(checksum, inputStream);

        // Act & Assert
        try {
            cis.read();
            org.junit.Assert.fail("Expected IOException to be thrown");
        } catch (IOException e) {
            assertEquals("Simulated IO error", e.getMessage());
        }
    }

    @Test
    public void testRead_IntegrationWithRealChecksum() throws IOException {
        // Arrange
        byte[] data = new byte[]{1, 2, 3};
        InputStream inputStream = new java.io.ByteArrayInputStream(data);
        CRC32 crc = new CRC32();
        CRC32 expectedCrc = new CRC32();
        expectedCrc.update(1);
        expectedCrc.update(2);
        expectedCrc.update(3);

        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc, inputStream);

        // Act
        cis.read(); // reads 1
        cis.read(); // reads 2
        cis.read(); // reads 3
        long actualValue = cis.getValue();

        // Assert
        assertEquals(expectedCrc.getValue(), actualValue);
    }
}
